<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Company,CompanyMembership,Supplier,SupplierAddress,SupplierContact}; use App\Services\{AuditLogger,AuthorizationService,ProcurementNumberService}; use App\Support\TenantContext; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Facades\DB;
final class SupplierController {
 private function t():string{return (string)app(TenantContext::class)->id();}
 private function canRead(Request $r):void{$t=$this->t();abort_unless($r->user()&&$r->user()->tenantMemberships()->where('tenant_id',$t)->where('status','active')->exists(),403);}
 private function can(Request $r,string $p='procurement.manage',?Supplier $s=null):void{$t=$this->t();abort_unless($r->user()&&app(AuthorizationService::class)->allows($r->user(),$t,$p,$s?->company_id),403);if($s)abort_unless($s->tenant_id===$t,404);}
 public function index(Request $r):JsonResponse{$this->canRead($r);$q=$this->supplierQuery($r);$sort=['name'=>'name','code'=>'code','status'=>'status','created_at'=>'created_at'][$r->string('sort','name')->toString()]??'name';$direction=$r->string('direction')->toString()==='desc'?'desc':'asc';return response()->json(['data'=>$q->orderBy($sort,$direction)->paginate(min(max($r->integer('per_page',25),10),100)),'summary'=>$this->summaryData($this->t(),$r)]);}
 public function summary(Request $r):JsonResponse{$this->can($r);return response()->json(['data'=>$this->summaryData($this->t(),$r)]);}
 private function supplierQuery(Request $r){return Supplier::where('tenant_id',$this->t())->with(['company','contacts','addresses'])->when($r->filled('company_id'),fn($x)=>$x->where(fn($y)=>$y->where('company_id',$r->string('company_id'))->orWhereNull('company_id')))->when($r->filled('status'),fn($x)=>$x->where('status',$r->string('status')))->when($r->filled('category'),fn($x)=>$x->where('category',$r->string('category')))->when($r->filled('supplier_type'),fn($x)=>$x->where('supplier_type',$r->string('supplier_type')))->when($r->filled('search'),function($x)use($r){$s=$r->string('search');$x->where(fn($y)=>$y->where('name','ilike',"%{$s}%")->orWhere('trading_name','ilike',"%{$s}%")->orWhere('code','ilike',"%{$s}%")->orWhere('email','ilike',"%{$s}%")->orWhere('phone','ilike',"%{$s}%"));})->when($r->date('date_from'),fn($x,$date)=>$x->whereDate('created_at','>=',$date))->when($r->date('date_to'),fn($x,$date)=>$x->whereDate('created_at','<=',$date));}
 private function summaryData(string $t,Request $r):array{$q=$this->supplierQuery($r);return ['total'=>$q->count(),'active'=>(clone $q)->where('status','active')->count(),'inactive'=>(clone $q)->where('status','inactive')->count(),'recently_added'=>(clone $q)->where('created_at','>=',now()->subDays(30))->count(),'recent_period_days'=>30];}
 public function show(Request $r,Supplier $supplier):JsonResponse{$this->canView($r,$supplier);return response()->json(['data'=>$supplier->load(['company','currency','contacts','addresses','purchaseOrders','bills'])]);}
 public function store(Request $r,ProcurementNumberService $numbers,AuditLogger $audit):JsonResponse{$this->can($r);$d=$this->validated($r);$t=$this->t();if(!empty($d['company_id'])){abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),422,'The selected company is not available in this tenant.');abort_unless(app(AuthorizationService::class)->allows($r->user(),$t,'procurement.manage',$d['company_id']),403);} $this->duplicateWarning($d);$s=DB::transaction(function()use($d,$r,$numbers){$t=$this->t();$supplier=Supplier::create([...$d,'tenant_id'=>$t,'code'=>$numbers->makeFor('SUP',$t,$d['company_id']??null),'created_by'=>$r->user()->id,'status'=>$d['status']??'active']);$this->syncPrimaryContact($supplier,$d);return $supplier;});$audit->record($r,'supplier.created',$this->t(),$s);return response()->json(['data'=>$s->load(['contacts','addresses'])],201);}
 public function update(Request $r,Supplier $supplier,AuditLogger $audit):JsonResponse{$this->can($r,'procurement.manage',$supplier);$d=$this->validated($r,true);$updated=DB::transaction(function()use($supplier,$d,$r):Supplier{$supplier->update([...$d,'updated_by'=>$r->user()->id]);$this->syncPrimaryContact($supplier,$d);return $supplier->fresh(['contacts','addresses']);});$audit->record($r,'supplier.updated',$this->t(),$updated);return response()->json(['data'=>$updated]);}
 public function activate(Request $r,Supplier $supplier,AuditLogger $audit):JsonResponse{$this->can($r,'procurement.manage',$supplier);$supplier->update(['status'=>'active','archived_at'=>null,'updated_by'=>$r->user()->id]);$audit->record($r,'supplier.activated',$this->t(),$supplier);return response()->json(['data'=>$supplier->fresh()]);}
 public function deactivate(Request $r,Supplier $supplier,AuditLogger $audit):JsonResponse{$this->can($r,'procurement.manage',$supplier);$supplier->update(['status'=>'inactive','updated_by'=>$r->user()->id]);$audit->record($r,'supplier.deactivated',$this->t(),$supplier);return response()->json(['data'=>$supplier->fresh()]);}
 public function contacts(Request $r,Supplier $supplier):JsonResponse{$this->can($r,'procurement.manage',$supplier);return response()->json(['data'=>$supplier->contacts()->latest()->get()]);}
 public function storeContact(Request $r,Supplier $supplier):JsonResponse{$this->can($r,'procurement.manage',$supplier);$d=$r->validate(['name'=>'required|string|max:200','job_title'=>'nullable|string|max:150','department'=>'nullable|string|max:150','email'=>'nullable|email','phone'=>'nullable|string|max:50','is_primary'=>'boolean','notes'=>'nullable|string','status'=>'nullable|in:active,inactive']);$c=DB::transaction(function()use($d,$supplier){if(!empty($d['is_primary']))$supplier->contacts()->update(['is_primary'=>false]);return $supplier->contacts()->create(['tenant_id'=>$this->t(),...$d]);});return response()->json(['data'=>$c],201);}
 public function updateContact(Request $r,SupplierContact $contact):JsonResponse{$s=$contact->supplier()->firstOrFail();$this->can($r,'procurement.manage',$s);$d=$r->validate(['name'=>'sometimes|string|max:200','job_title'=>'nullable|string|max:150','department'=>'nullable|string|max:150','email'=>'nullable|email','phone'=>'nullable|string|max:50','is_primary'=>'boolean','notes'=>'nullable|string','status'=>'nullable|in:active,inactive']);if(!empty($d['is_primary']))$s->contacts()->where('id','<>',$contact->id)->update(['is_primary'=>false]);$contact->update($d);return response()->json(['data'=>$contact->fresh()]);}
 public function addresses(Request $r,Supplier $supplier):JsonResponse{$this->can($r,'procurement.manage',$supplier);return response()->json(['data'=>$supplier->addresses()->latest()->get()]);}
 public function storeAddress(Request $r,Supplier $supplier):JsonResponse{$this->can($r,'procurement.manage',$supplier);$d=$r->validate(['address_type'=>'required|in:registered_office,billing,collection_shipping,other','recipient'=>'nullable|string|max:200','country'=>'nullable|string|max:100','region'=>'nullable|string|max:100','city'=>'nullable|string|max:100','township'=>'nullable|string|max:100','postal_code'=>'nullable|string|max:30','street_address'=>'required|string|max:2000','is_default'=>'boolean','status'=>'nullable|in:active,inactive']);$a=DB::transaction(function()use($d,$supplier){if(!empty($d['is_default']))$supplier->addresses()->where('address_type',$d['address_type'])->update(['is_default'=>false]);return $supplier->addresses()->create(['tenant_id'=>$this->t(),...$d]);});return response()->json(['data'=>$a],201);}
 public function updateAddress(Request $r,SupplierAddress $address):JsonResponse{$s=$address->supplier()->firstOrFail();$this->can($r,'procurement.manage',$s);$d=$r->validate(['address_type'=>'sometimes|in:registered_office,billing,collection_shipping,other','recipient'=>'nullable|string|max:200','country'=>'nullable|string|max:100','region'=>'nullable|string|max:100','city'=>'nullable|string|max:100','township'=>'nullable|string|max:100','postal_code'=>'nullable|string|max:30','street_address'=>'sometimes|string|max:2000','is_default'=>'boolean','status'=>'nullable|in:active,inactive']);$address->update($d);return response()->json(['data'=>$address->fresh()]);}
 private function canView(Request $r,Supplier $supplier):void{$t=$this->t();abort_unless($supplier->tenant_id===$t,404);if(app(AuthorizationService::class)->allows($r->user(),$t,'procurement.manage',$supplier->company_id))return;if($supplier->company_id)abort_unless(CompanyMembership::where('tenant_id',$t)->where('company_id',$supplier->company_id)->where('user_id',$r->user()->id)->where('status','active')->exists(),403);else $this->canRead($r);}
 private function validated(Request $r,bool $update=false):array{return $r->validate(['company_id'=>$update?'prohibited':'nullable|uuid','name'=>[$update?'sometimes':'required','string','max:200'],'trading_name'=>'nullable|string|max:200','supplier_type'=>'nullable|in:business,individual','category'=>'nullable|string|max:100','email'=>'nullable|email','phone'=>'nullable|string|max:50','alternative_phone'=>'nullable|string|max:50','address'=>'nullable|string|max:2000','tax_identifier'=>'nullable|string|max:100','business_registration_number'=>'nullable|string|max:100','website'=>'nullable|url|max:255','description'=>'nullable|string','contact_person_name'=>'nullable|string|max:200','contact_person_job_title'=>'nullable|string|max:150','contact_person_email'=>'nullable|email','contact_person_phone'=>'nullable|string|max:50','preferred_currency_id'=>'nullable|uuid','payment_terms'=>'nullable|string|max:500','preferred_communication_method'=>'nullable|string|max:50','internal_notes'=>'nullable|string','status'=>'nullable|in:active,inactive,archived']);}
 private function syncPrimaryContact(Supplier $supplier,array $data):void{ $name=trim((string)($data['contact_person_name']??'')); if($name===''){return;} $contact=array_filter(['name'=>$name,'job_title'=>$data['contact_person_job_title']??null,'email'=>$data['contact_person_email']??null,'phone'=>$data['contact_person_phone']??null],static fn($value):bool=>$value!==null&&trim((string)$value)!==''); $primary=$supplier->contacts()->where('is_primary',true)->first(); if($primary){$primary->update([...$contact,'status'=>'active']);}else{$supplier->contacts()->create(['tenant_id'=>$this->t(),...$contact,'is_primary'=>true,'status'=>'active']);} }
 private function duplicateWarning(array $d):void{if(!empty($d['business_registration_number'])||!empty($d['tax_identifier'])){$q=Supplier::where('tenant_id',$this->t())->where(function($x)use($d){if(!empty($d['business_registration_number']))$x->orWhere('business_registration_number',$d['business_registration_number']);if(!empty($d['tax_identifier']))$x->orWhere('tax_identifier',$d['tax_identifier']);});if($q->exists())abort(409,'A supplier with the same registration or tax identifier already exists in this tenant.');}}
}
